UPDATE BID_ASSIGN_CASE SET PENDING_REQ_ID = #{reqId}
 WHERE BID_CASE_ID = #{bidCaseId} AND GROUP_VER = #{groupVer}
   AND (PENDING_REQ_ID IS NULL OR PENDING_REQ_ID = #{staleReqId,jdbcType=NUMERIC})

UPDATE BID_ASSIGN_CASE SET GROUP_VER = GROUP_VER + 1, PENDING_REQ_ID = NULL,
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE BID_CASE_ID = #{bidCaseId} AND GROUP_VER = #{groupVer} AND PENDING_REQ_ID = #{reqId}
